#!/usr/bin/env node
// R216-1: the web country catalogue is GENERATED from the single authoritative Core catalogue
// (apps/core-api/src/main/resources/catalogues/iso-3166-1-alpha-2.txt). Run without arguments to
// regenerate, or with --check to fail when the generated file has drifted.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const SOURCE = resolve(
  root,
  'apps/core-api/src/main/resources/catalogues/iso-3166-1-alpha-2.txt',
);
export const TARGET = resolve(root, 'apps/web/src/features/partners/countryCodes.generated.ts');

export function readCatalogue(path = SOURCE) {
  return readFileSync(path, 'utf8')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
}

export function render(codes) {
  const lines = codes.map((code) => `  '${code}',`).join('\n');
  return `// GENERATED by scripts/ops/partner-countries.mjs from the Core country catalogue
// (apps/core-api/src/main/resources/catalogues/iso-3166-1-alpha-2.txt). Do not edit by hand.
// Assigned ISO 3166-1 alpha-2 codes only; display names come from Intl.DisplayNames.

export const COUNTRY_CODES: readonly string[] = [
${lines}
];
`;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const expected = render(readCatalogue());
  if (process.argv.includes('--check')) {
    let actual = '';
    try {
      actual = readFileSync(TARGET, 'utf8');
    } catch {
      // missing file is drift
    }
    if (actual !== expected) {
      console.error(
        'countryCodes.generated.ts is out of date: run node scripts/ops/partner-countries.mjs',
      );
      process.exit(1);
    }
    console.log('countryCodes.generated.ts matches the Core catalogue');
  } else {
    writeFileSync(TARGET, expected);
    console.log(`Generated ${TARGET}`);
  }
}
